<?php
session_start();
header('Content-Type: application/json; charset=utf-8');
require_once __DIR__ . '/db.php';
function out($data, $status=200){ http_response_code($status); echo json_encode($data); exit; }
function require_user(){ if(empty($_SESSION['user_id'])) out(['error'=>'Please log in first.'],401); return (int)$_SESSION['user_id']; }
$action=$_GET['action'] ?? '';
try {
 if($action==='recent_materials'){
  $st=$pdo->query("SELECT m.id,m.title,m.course,m.subject,m.academic_year,m.material_type,u.full_name AS uploader FROM materials m JOIN users u ON u.id=m.uploaded_by WHERE m.status='approved' ORDER BY m.created_at DESC LIMIT 3");out(['materials'=>$st->fetchAll(PDO::FETCH_ASSOC)]);
 }
 if($action==='materials'){
   require_user();
   $where="m.status='approved'"; $params=[];
   if(!empty($_GET['q'])){$where.=" AND (m.title LIKE :q OR m.description LIKE :q OR m.subject LIKE :q OR m.course LIKE :q OR m.material_type LIKE :q)";$params[':q']='%'.$_GET['q'].'%';}
   $st=$pdo->prepare("SELECT m.id,m.title,m.description,m.course,m.subject,m.academic_year,m.material_type,m.file_path,m.created_at,u.full_name AS uploader FROM materials m JOIN users u ON u.id=m.uploaded_by WHERE $where ORDER BY m.created_at DESC");$st->execute($params);out(['materials'=>$st->fetchAll(PDO::FETCH_ASSOC)]);
 }
 if($action==='material'){require_user();$id=(int)($_GET['id']??0);if(!$id)out(['error'=>'Invalid material.'],400);$st=$pdo->prepare("SELECT m.id,m.title,m.description,m.course,m.subject,m.academic_year,m.material_type,m.file_path,m.created_at,u.full_name AS uploader FROM materials m JOIN users u ON u.id=m.uploaded_by WHERE m.id=? AND m.status='approved'");$st->execute([$id]);$material=$st->fetch(PDO::FETCH_ASSOC);if(!$material)out(['error'=>'Material not found or not approved.'],404);$st=$pdo->prepare('SELECT ROUND(AVG(rating),1) AS average_rating,COUNT(*) AS rating_count FROM ratings WHERE material_id=?');$st->execute([$id]);$material['average_rating']=$st->fetch(PDO::FETCH_ASSOC);out(['material'=>$material]);}
 if($action==='my_uploads'){$id=require_user();$st=$pdo->prepare('SELECT id,title,description,course,subject,academic_year,material_type,status,file_path,created_at FROM materials WHERE uploaded_by=? ORDER BY created_at DESC');$st->execute([$id]);out(['materials'=>$st->fetchAll(PDO::FETCH_ASSOC)]);}
 if($action==='downloads'){$id=require_user();$st=$pdo->prepare('SELECT m.id,m.title,m.course,m.subject,m.academic_year,m.material_type,m.file_path,m.status,d.downloaded_at FROM downloads d JOIN materials m ON m.id=d.material_id WHERE d.user_id=? ORDER BY d.downloaded_at DESC');$st->execute([$id]);out(['materials'=>$st->fetchAll(PDO::FETCH_ASSOC)]);}
 if($action==='profile'){$id=require_user();$st=$pdo->prepare('SELECT full_name,email,program,year_of_study,role,profile_photo,created_at FROM users WHERE id=?');$st->execute([$id]);$user=$st->fetch(PDO::FETCH_ASSOC);if(!$user)out(['error'=>'Account not found.'],404);out(['user'=>$user]);}
 if($action==='update_profile' && $_SERVER['REQUEST_METHOD']==='POST'){$id=require_user();$name=trim($_POST['full_name']??'');$program=trim($_POST['program']??'');$year=$_POST['year_of_study']??'';if($name===''||$program===''||!in_array($year,['year-1','year-2','year-3','year-4'],true))out(['error'=>'Enter a name, program, and valid year of study.'],400);$st=$pdo->prepare('UPDATE users SET full_name=?,program=?,year_of_study=? WHERE id=?');$st->execute([$name,$program,$year,$id]);$_SESSION['full_name']=$name;out(['ok'=>true]);}
 if($action==='upload_profile_photo' && $_SERVER['REQUEST_METHOD']==='POST'){$id=require_user();$file=$_FILES['profile_photo']??null;if(!$file||$file['error']!==UPLOAD_ERR_OK)out(['error'=>'Choose a profile photo to upload.'],400);if($file['size']>5*1024*1024)out(['error'=>'Profile photos must be 5 MB or smaller.'],400);$imageInfo=@getimagesize($file['tmp_name']);if($imageInfo===false)out(['error'=>'Choose a valid image file.'],400);$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$extensions=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($extensions[$mime]))out(['error'=>'Only JPG, PNG, and WebP images are accepted.'],400);$dir=dirname(__DIR__).'/uploads/profile-images';if(!is_dir($dir)&&!mkdir($dir,0755,true))out(['error'=>'Could not create the profile photo folder.'],500);$name=bin2hex(random_bytes(16)).'.'.$extensions[$mime];$destination=$dir.'/'.$name;if(!move_uploaded_file($file['tmp_name'],$destination))out(['error'=>'Could not save the profile photo.'],500);$path='../uploads/profile-images/'.$name;try{$st=$pdo->prepare('UPDATE users SET profile_photo=? WHERE id=?');$st->execute([$path,$id]);out(['ok'=>true,'profile_photo'=>$path]);}catch(Throwable $e){@unlink($destination);throw $e;}}
 if($action==='session'){$id=require_user();out(['user_id'=>$id,'role'=>$_SESSION['role']??'']);}
 if($action==='users'){if(($_SESSION['role']??'')!=='admin')out(['error'=>'Admin access required.'],403);$st=$pdo->query('SELECT full_name,email,program,year_of_study,role,created_at FROM users ORDER BY created_at DESC');out(['users'=>$st->fetchAll(PDO::FETCH_ASSOC)]);}
 if(in_array($action,['pending','approved','rejected'],true)){if(($_SESSION['role']??'')!=='admin')out(['error'=>'Admin access required.'],403);$st=$pdo->prepare('SELECT m.*,u.full_name AS uploader FROM materials m JOIN users u ON u.id=m.uploaded_by WHERE m.status=? ORDER BY m.created_at DESC');$st->execute([$action]);out(['materials'=>$st->fetchAll(PDO::FETCH_ASSOC)]);}
 if($action==='reports'){if(($_SESSION['role']??'')!=='admin')out(['error'=>'Admin access required.'],403);$st=$pdo->query("SELECT r.id,r.material_id,r.reason,r.details,r.status,r.created_at,m.title AS material_title,u.full_name AS reporter FROM reports r JOIN materials m ON m.id=r.material_id JOIN users u ON u.id=r.reporter_id ORDER BY r.created_at DESC");out(['reports'=>$st->fetchAll(PDO::FETCH_ASSOC)]);}
 if($action==='subscriptions'){if(($_SESSION['role']??'')!=='admin')out(['error'=>'Admin access required.'],403);$st=$pdo->query('SELECT s.id,s.plan,s.amount,s.currency,s.status,s.created_at,s.paid_at,s.expires_at,u.full_name,u.email FROM subscriptions s JOIN users u ON u.id=s.user_id ORDER BY s.created_at DESC');out(['subscriptions'=>$st->fetchAll(PDO::FETCH_ASSOC)]);}
 if($action==='moderate' && $_SERVER['REQUEST_METHOD']==='POST'){if(($_SESSION['role']??'')!=='admin')out(['error'=>'Admin access required.'],403);$id=(int)($_POST['id']??0);$status=$_POST['status']??'';if(!$id||!in_array($status,['approved','rejected'],true))out(['error'=>'Invalid moderation request.'],400);$st=$pdo->prepare('UPDATE materials SET status=? WHERE id=?');$st->execute([$status,$id]);out(['ok'=>true]);}
 if($action==='rate' && $_SERVER['REQUEST_METHOD']==='POST'){$uid=require_user();$mid=(int)($_POST['material_id']??0);$rating=(int)($_POST['rating']??0);$comment=trim($_POST['comment']??'');if($rating<1||$rating>5||!$mid)out(['error'=>'Choose a rating from 1 to 5.'],400);$st=$pdo->prepare("SELECT id FROM materials WHERE id=? AND status='approved'");$st->execute([$mid]);if(!$st->fetchColumn())out(['error'=>'Material not found or not approved.'],404);$st=$pdo->prepare("INSERT INTO ratings(user_id,material_id,rating,comment) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE rating=VALUES(rating),comment=VALUES(comment)");$st->execute([$uid,$mid,$rating,$comment]);out(['ok'=>true]);}
 if($action==='report' && $_SERVER['REQUEST_METHOD']==='POST'){$uid=require_user();$mid=(int)($_POST['material_id']??0);$reason=trim($_POST['reason']??'');$details=trim($_POST['details']??'');if(!$mid||$reason==='')out(['error'=>'Select a reason.'],400);$st=$pdo->prepare("SELECT id FROM materials WHERE id=? AND status='approved'");$st->execute([$mid]);if(!$st->fetchColumn())out(['error'=>'Material not found or not approved.'],404);$st=$pdo->prepare('INSERT INTO reports(reporter_id,material_id,reason,details) VALUES(?,?,?,?)');$st->execute([$uid,$mid,$reason,$details]);out(['ok'=>true]);}
 if($action==='report_status' && $_SERVER['REQUEST_METHOD']==='POST'){if(($_SESSION['role']??'')!=='admin')out(['error'=>'Admin access required.'],403);$id=(int)($_POST['id']??0);$status=$_POST['status']??'';if(!$id||!in_array($status,['reviewed','resolved'],true))out(['error'=>'Invalid report update.'],400);$st=$pdo->prepare('UPDATE reports SET status=? WHERE id=?');$st->execute([$status,$id]);if(!$st->rowCount())out(['error'=>'Report not found or already has that status.'],404);out(['ok'=>true]);}
 if(in_array($action,['payment_init','verify_payment'],true)){
   out(['error'=>'Premium subscriptions are paused. All approved study materials are available to students for free.'],410);
 }
 out(['error'=>'Unknown action.'],404);
} catch(Throwable $e){error_log('ShareStudy API: '.$e->getMessage());out(['error'=>'A database operation failed. Check the PHP error log and database tables.'],500);}
